function renderThemeControl(){const button=$('themeToggle'),label=theme==='dark'?ui[language].toLight:ui[language].toDark;button.innerHTML=`<span aria-hidden="true">${theme==='dark'?'☀':'☾'}</span><span class="theme-text">${label.slice(2)}</span>`;button.setAttribute('aria-label',label);button.setAttribute('aria-pressed',String(theme==='dark'));button.title=label;}
