function settingNotes(stage,values,key){const ar=language==='ar',n=[];
 switch(stage.id){
 case 'ingestion':if(values[2]==='often'||values[5]==='yes')n.push(ar?'احفظ معرّف المصدر ووقت التحديث لتجنب الفهرسة المكررة.':'Keep source IDs and update times to avoid duplicate indexing.');if(values[3]==='private')n.push(ar?'عالج المصدر داخل بيئتك الموثوقة.':'Process this source in your trusted environment.');if(values[4]==='large')n.push(ar?'استخدم دفعات وفهرسة تدريجية عند زيادة الحجم.':'Use batches and incremental indexing as volume grows.');break;
 case 'preprocessing':if(values[4]==='yes')n.push(ar?'المستندات الممسوحة تحتاج OCR؛ راجع النص المستخرج قبل الفهرسة.':'Scans need OCR; inspect extracted text before indexing.');if(values[4]==='yes'&&values[0]==='pii')n.push(ar?'بعد OCR افحص البيانات الشخصية قبل إرسال النص لأي خدمة.':'After OCR, screen personal data before sending text to a service.');if(values[3]==='ar'||values[3]==='multi')n.push(ar?'تحقق من ترتيب القراءة والتشكيل وحروف العربية في النص المستخرج.':'Check reading order and Arabic characters in extracted text.');if(values[0]==='pii'&&values[3]!=='en')n.push(ar?'كشف البيانات الشخصية بالعربية يحتاج إضافة نموذج لغة وقواعد تعرف مناسبة؛ الإعداد الافتراضي الإنجليزي لا يكفي.':'Arabic PII detection needs suitable language models and recognizers; the English defaults are insufficient.');if(values[5]==='near')n.push(ar?'إزالة التكرار المتشابه تحتاج اختبار عتبة حتى لا تحذف فقرات مختلفة.':'Near-duplicate removal needs a tested threshold to avoid deleting distinct passages.');break;
 case 'chunking':{const size={small:450,medium:800,large:1200}[values[1]],overlap=values[2]==='yes'?Math.round(size*.15):0;n.push(ar?`ابدأ بحجم ${size} حرف وتداخل ${overlap}، ثم قِس جودة الاسترجاع.`:`Start with ${size} characters and ${overlap} overlap, then measure retrieval.`);if(values[4]==='yes')n.push(ar?'اترك صفوف الجدول وعناوينه معًا ما أمكن.':'Keep table rows and their headers together where possible.');if(values[5]==='yes')n.push(ar?'احتفظ بمعرف المستند والصفحة مع كل جزء.':'Preserve document and page IDs on each chunk.');break;}
 case 'vector':{const dim=values[3]==='auto'?(embeddingSelection?.dim||null):Number(values[3]);n.push(dim?(ar?`اضبط أبعاد الفهرس على ${dim} لتطابق موديل Embedding.`:`Set index dimensions to ${dim} to match the embedding model.`):(ar?'اختر موديل Embedding أولًا لتحديد الأبعاد الصحيحة.':'Choose an embedding model first to determine dimensions.'));if(values[3]!=='auto'&&embeddingSelection?.dim&&dim!==embeddingSelection.dim)n.push(ar?`تنبيه: الموديل المختار ينتج ${embeddingSelection.dim} بُعدًا؛ غيّر هذا الإعداد إلى ${embeddingSelection.dim} أو اختر «حسب الموديل».`:`Warning: your selected model outputs ${embeddingSelection.dim} dimensions; use that value or choose “From Embedding model”.`);if(values[4]==='yes')n.push(ar?'البحث الهجين يحتاج تمثيلًا كثيفًا وآخر للكلمات أو المتجهات المتناثرة.':'Hybrid search needs dense and keyword or sparse representations.');if(values[5]==='needed')n.push(ar?'خطط لنسخ احتياطي واستعادة للفهرس والبيانات الوصفية.':'Plan backup and restore for vectors and metadata.');break;}
 case 'retrieval':n.push(ar?`ابدأ بإرجاع ${values[3]} مقاطع، ثم غيّر العدد بعد قياس الاسترجاع.`:`Start with ${values[3]} passages, then tune after retrieval evaluation.`);if(values[4]==='yes')n.push(ar?'طبّق فلترة metadata قبل ترتيب النتائج إذا كانت ضرورية للصلاحيات.':'Apply metadata filters before ranking when access rules require them.');if(key==='hybrid')n.push(ar?'احتفظ بفهرس كلمات BM25 بجانب قاعدة المتجهات المختارة ثم ادمج النتائج.':'Keep a BM25 keyword index alongside your chosen vector store, then fuse the results.');break;
 case 'reranking':n.push(ar?`أعِد ترتيب ${values[3]} مرشحًا واحتفظ بأفضل ${values[4]} نتائج.`:`Rerank ${values[3]} candidates and keep the best ${values[4]}.`);if(values[5]==='private')n.push(ar?'استُبعدت خدمة API لأن المقاطع خاصة.':'API reranking is excluded because passages are private.');break;
 case 'prompt':if(values[0]==='yes')n.push(ar?'أبقِ أرقام المصادر في السياق واطلب الاستشهاد بها في الإجابة.':'Keep source numbers in context and ask the model to cite them.');if(values[5]==='strict')n.push(ar?'عامل نصوص المستندات كبيانات، لا كتعليمات للموديل.':'Treat retrieved text as data, never as model instructions.');n.push(ar?`ميزانية السياق ${values[3]==='small'?'صغيرة':values[3]==='medium'?'متوسطة':'كبيرة'}؛ قلّل عدد المقاطع إذا تجاوزت الحد.`:`Context budget: ${values[3]}; reduce passages if it is exceeded.`);break;
 case 'generation':if(values[3]==='private')n.push(ar?'تم اختيار التشغيل المحلي للحفاظ على خصوصية النصوص.':'Local generation was selected to keep project text private.');if(values[4]==='json')n.push(ar?'تحقق من صحة JSON بعد التوليد قبل استخدامه برمجيًا.':'Validate generated JSON before using it in code.');break;
 case 'evaluation':n.push(ar?`ابدأ بمجموعة من ${values[3]} سؤالًا تمثل حالات مشروعك.`:`Start with ${values[3]} questions that represent your project.`);if(values[1]==='no')n.push(ar?'أنشئ أمثلة مرجعية قبل حساب مقاييس تحتاج إجابات أو مقاطع صحيحة.':'Create reference examples before computing metrics that need known answers or passages.');break;
 }
 return n;}
function questionHTML(stage,q,qi,values){return `<div class="question"><div class="question-label"><span>${String(qi+1).padStart(2,'0')}</span>${t(q.label)}</div><div class="options">${q.options.map(o=>`<button class="option ${values[qi]===o[0]?'selected':''}" type="button" data-question="${qi}" data-option="${o[0]}" aria-pressed="${values[qi]===o[0]}">${o[language==='ar'?1:2]}</button>`).join('')}</div></div>`;}
function renderStage(){if(active<0)return;const stage=stages[active],s=ui[language];$('backText').textContent=s.back;$('stageCounter').textContent=`${String(active+1).padStart(2,'0')} / 10`;$('stagePill').textContent=`${s.pill} ${String(active+1).padStart(2,'0')}`;$('stageTitle').textContent=t(stage.name);$('stageIntro').textContent=t(stage.intro);$('stageGlyph').innerHTML=stageIcon(active);$('questionsTitle').textContent=s.questions;$('questionsIntro').textContent=s.questionsIntro;$('recommendTitle').textContent=s.rec;$('recommendIntro').textContent=s.recIntro;
 $('guidedStage').hidden=active===3;$('embeddingStage').hidden=active!==3;
 $('previousStage').textContent=active===0?s.home:`← ${s.previous}`;$('nextStage').textContent=active===9?s.home:`${s.next} →`;
 if(active===3){const frame=$('embeddingFrame');if(frame.contentWindow)frame.contentWindow.postMessage({type:'embedpilot-language',language},'*');return;}
 const values=normalizedAnswers(stage);answers[stage.id]=values;
 const basic=stage.questions.slice(0,stage.basicQuestionCount).map((q,i)=>questionHTML(stage,q,i,values)).join('');
 const extra=stage.questions.slice(stage.basicQuestionCount).map((q,i)=>questionHTML(stage,q,i+stage.basicQuestionCount,values)).join('');
 $('questions').innerHTML=basic+(extra?`<button type="button" id="advancedToggle" class="advanced-toggle" aria-expanded="${!!advancedOpen[stage.id]}"><span>${advancedOpen[stage.id]?s.advancedOpen:s.advancedClosed} · ${stage.questions.length-stage.basicQuestionCount}</span><span class="chevron">⌄</span></button><div class="advanced-questions" ${advancedOpen[stage.id]?'':'hidden'}>${extra}</div>`:'');
 if(extra)$('advancedToggle').onclick=()=>{advancedOpen[stage.id]=!advancedOpen[stage.id];renderStage();};
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{answers[stage.id][Number(b.dataset.question)]=b.dataset.option;save();renderStage();});
 const key=recommendedKey(stage,values),rec=stage.recs[key],reasons=[t(rec.why),...settingNotes(stage,values,key)];
 const settingRows=chosenSettings(stage,values).map(item=>`<div><dt>${item.label}</dt><dd>${item.value}</dd></div>`).join('');
 $('recommendation').innerHTML=`<div class="recommend-card"><div class="rec-kicker">${s.recommended}</div><h3>${rec.name}</h3><div class="rec-id">${rec.id}</div><p><strong>${s.why}</strong></p><ul class="reason-list">${reasons.map(r=>`<li>${r}</li>`).join('')}</ul><a class="rec-link" href="${rec.url}" target="_blank" rel="noopener noreferrer">${s.docs}</a></div><div class="settings-summary"><strong>${s.selectedSettings}</strong><dl>${settingRows}</dl></div><div class="code-card"><div class="code-switch" role="group" aria-label="Code style"><button type="button" data-code-mode="direct">${s.plainCode}</button><button type="button" data-code-mode="langchain">${s.langchainCode}</button></div><div class="install-line"><strong>${s.install}</strong><code id="installCommand"></code></div><div class="code-head"><span id="codeLanguage"></span><button type="button" class="copy-code" id="copyCode">${s.copy}</button></div><pre id="codeText"></pre></div><p class="code-note">${s.codeNote}</p>`;
 const snippets={direct:window.KhamisCode.direct(stage.id,key,rec,values,{embeddingDim:embeddingSelection?.dim}),langchain:window.KhamisCode.langchain(stage.id,key,rec,values,{embeddingDim:embeddingSelection?.dim})};
 function showCode(){const mode=codeModes[stage.id]==='langchain'?'langchain':'direct';$('codeText').textContent=snippets[mode];$('codeLanguage').textContent=`${mode==='direct'&&key==='pgvector'?'SQL':'PYTHON'} · ${rec.id}`;$('installCommand').textContent=window.KhamisCode.install(stage.id,key,mode)||s.noInstall;document.querySelectorAll('[data-code-mode]').forEach(b=>{const selected=b.dataset.codeMode===mode;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});}
 document.querySelectorAll('[data-code-mode]').forEach(b=>b.onclick=()=>{codeModes[stage.id]=b.dataset.codeMode;showCode();save();});
 $('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText($('codeText').textContent);$('copyCode').textContent=s.copied;}catch{$('copyCode').textContent=s.copyFail;}};showCode();save();}
function showOnly(view){if(view!=='complexityView')window.KhamisComplexity.pause();for(const id of ['home','stagesHome','simulationView','ecosystemsView','reposView','coursesView','aiCompaniesView','mathSkillsView','complexityView','stageView'])$(id).hidden=id!==view;}
function openStage(i){active=i;window.KhamisSimulation.pause();showOnly('stageView');renderStage();renderNav();window.location.hash=`stage-${i+1}`;window.scrollTo({top:0,behavior:'smooth'});}
function openSimulation(){active=-2;showOnly('simulationView');window.KhamisSimulation.resume();renderNav();window.location.hash='simulation';window.scrollTo({top:0,behavior:'smooth'});}
function openEcosystems(){active=-3;window.KhamisSimulation.pause();showOnly('ecosystemsView');window.KhamisEcosystems.render(language);renderNav();window.location.hash='ecosystems';window.scrollTo({top:0,behavior:'smooth'});}
const resourceRoutes={repos:{view:'reposView',active:-7},courses:{view:'coursesView',active:-8},companies:{view:'aiCompaniesView',active:-9}};
function openResource(kind){const route=resourceRoutes[kind];active=route.active;window.KhamisSimulation.pause();showOnly(route.view);window.KhamisResources.render(kind,language);renderNav();window.location.hash=kind==='companies'?'ai-companies':kind;window.scrollTo({top:0,behavior:'smooth'});}
function openMath(){active=-4;window.KhamisSimulation.pause();showOnly('mathSkillsView');window.KhamisMathSkills.render(language);renderNav();window.location.hash='math-skills';window.scrollTo({top:0,behavior:'smooth'});}
function openComplexity(){active=-5;window.KhamisSimulation.pause();showOnly('complexityView');window.KhamisComplexity.open(language);renderNav();window.location.hash='complexity';window.scrollTo({top:0,behavior:'smooth'});}
function openStages(){active=-1;window.KhamisSimulation.pause();showOnly('stagesHome');renderNav();window.location.hash='stages';window.scrollTo({top:0,behavior:'smooth'});}
function goHome(){active=-1;window.KhamisSimulation.pause();showOnly('stagesHome');renderNav();history.replaceState(null,'',location.pathname+location.search);window.scrollTo({top:0,behavior:'smooth'});}
function setLanguage(value){language=value;document.documentElement.lang=value;document.documentElement.dir=value==='ar'?'rtl':'ltr';renderHome();renderStage();renderThemeControl();window.KhamisSimulation.init(value,stageIcon);if(active===-3){window.KhamisSimulation.pause();window.KhamisEcosystems.render(value);}if(active===-4)window.KhamisMathSkills.render(value);if(active===-5)window.KhamisComplexity.render(value);for(const [kind,route] of Object.entries(resourceRoutes))if(active===route.active)window.KhamisResources.render(kind,value);renderNav();save();}
$('language').onclick=()=>setLanguage(language==='ar'?'en':'ar');$('themeToggle').onclick=()=>setTheme(theme==='dark'?'light':'dark');$('homeBrand').onclick=goHome;$('navStages').onclick=openStages;$('navEcosystems').onclick=openEcosystems;$('navRepos').onclick=()=>openResource('repos');$('navCourses').onclick=()=>openResource('courses');$('navCompanies').onclick=()=>openResource('companies');$('backHome').onclick=openStages;$('previousStage').onclick=()=>active===0?openStages():openStage(active-1);$('nextStage').onclick=()=>active===9?openStages():openStage(active+1);
$('startButton').onclick=()=>openStage(0);
$('motionToggle').onclick=()=>{motionEnabled=!motionEnabled;renderMotionControl();save();};
$('orbit').addEventListener('pointerenter',()=>{motionPausedByPointer=true;});
$('orbit').addEventListener('pointerleave',()=>{motionPausedByPointer=false;});
$('embeddingFrame').addEventListener('load',()=>{$('embeddingFrame').contentWindow?.postMessage({type:'embedpilot-language',language},'*');$('embeddingFrame').contentWindow?.postMessage({type:'khamisragtools-theme',theme},'*');});window.addEventListener('message',event=>{if(event.source!==$('embeddingFrame').contentWindow)return;if(event.data?.type==='embedpilot-language-changed'&&['ar','en'].includes(event.data.language))setLanguage(event.data.language);if(event.data?.type==='khamisragtools-embed-height'&&Number.isFinite(event.data.height))$('embeddingFrame').style.height=`${Math.max(700,Math.ceil(event.data.height)+12)}px`;if(event.data?.type==='khamisragtools-embedding-selection'&&Number.isInteger(event.data.dim)&&event.data.dim>0){embeddingSelection={key:event.data.key,name:event.data.name,id:event.data.id,dim:event.data.dim,mode:event.data.mode};save();if(active===4)renderStage();}});
function syncHash(){if(location.hash==='#stages'){active=-1;showOnly('stagesHome');window.KhamisSimulation.pause();renderNav();return;}if(location.hash==='#complexity'){active=-5;showOnly('complexityView');window.KhamisSimulation.pause();window.KhamisComplexity.open(language);renderNav();return;}if(location.hash==='#math-skills'){active=-4;showOnly('mathSkillsView');window.KhamisSimulation.pause();window.KhamisMathSkills.render(language);renderNav();return;}if(location.hash==='#ecosystems'){active=-3;showOnly('ecosystemsView');window.KhamisSimulation.pause();window.KhamisEcosystems.render(language);renderNav();return;}for(const [kind,route] of Object.entries(resourceRoutes))if(location.hash==='#'+(kind==='companies'?'ai-companies':kind)){active=route.active;showOnly(route.view);window.KhamisSimulation.pause();window.KhamisResources.render(kind,language);renderNav();return;}if(location.hash==='#simulation'){active=-2;showOnly('simulationView');window.KhamisSimulation.resume();renderNav();return;}const match=location.hash.match(/^#stage-(\d+)$/);const i=match?Number(match[1])-1:-1;if(i>=0&&i<stages.length){active=i;showOnly('stageView');window.KhamisSimulation.pause();renderStage();}else{active=-1;showOnly('stagesHome');window.KhamisSimulation.pause();}renderNav();}
window.addEventListener('hashchange',syncHash);setTheme(theme);setLanguage(language);syncHash();requestAnimationFrame(advanceOrbit);
